#include <bits/stdc++.h>
using namespace std;
struct PS { int tu, mau; };
int ucln(int a, int b) {
    a = abs(a); b = abs(b);
    while (b) { int r = a % b; a = b; b = r; }
    return a;
}
int main() {
    PS p = {12, -18};
    int g = ucln(p.tu, p.mau);
    p.tu /= g; p.mau /= g;
    if (p.mau < 0) { p.tu = -p.tu; p.mau = -p.mau; }
    cout << p.tu << "/" << p.mau;
}

#include <bits/stdc++.h>
using namespace std;
struct PS { int tu, mau; };
PS cong(PS a, PS b) {
    return { a.tu * b.mau + b.tu * a.mau, a.mau * b.mau };
}
int main() {
    PS a = {1, 2}, b = {1, 3};
    PS x = cong(a, b);
    cout << x.tu << "/" << x.mau << " ";
    cout << a.tu + b.tu << "/" << a.mau + b.mau;
}

#include <bits/stdc++.h>
