bool nhuan(int y) { return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0; }
int ngayTrongThang(int m, int y) {
    switch (m) {
        case 2: return nhuan(y) ? 29 : 28;
        case 4: case 6: case 9: case 11: return 30;
        default: return 31;
    }
}
