    cout << ngayTrongThang(2, 2024) << " " << ngayTrongThang(2, 1900) << " "
         << ngayTrongThang(2, 2000) << " " << ngayTrongThang(4, 2023);
}

#include <bits/stdc++.h>
using namespace std;
struct Ngay { int d, m, y; };
bool nhuan(int y) { return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0; }
int soNgay(int m, int y) {
    if (m == 2) return nhuan(y) ? 29 : 28;
    return (m == 4 || m == 6 || m == 9 || m == 11) ? 30 : 31;
}
Ngay ngayMai(Ngay a) {
    a.d++;
    if (a.d > soNgay(a.m, a.y)) {
        a.d = 1; a.m++;
        if (a.m > 12) { a.m = 1; a.y++; }
    }
    return a;
}
int main() {
    Ngay x = ngayMai({28, 2, 2024}), y = ngayMai({31, 12, 2023});
    cout << x.d << "/" << x.m << "/" << x.y << " " << y.d << "/" << y.m << "/" << y.y;
}

#include <bits/stdc++.h>
using namespace std;
struct Diem { double x, y; };
double kc(Diem a, Diem b) {
    return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}
int main() {
    Diem A = {0, 0}, B = {3, 0}, C = {0, 4};
    double cv = kc(A, B) + kc(B, C) + kc(C, A);
    double dt = fabs((B.x - A.x) * (C.y - A.y) - (C.x - A.x) * (B.y - A.y)) / 2;
    cout << fixed << setprecision(2) << cv << " " << dt;
}

