#include <bits/stdc++.h>
using namespace std;
struct HS { string ten; double dtb; };
void sapXep(HS a[], int n) {
    for (int i = 0; i < n - 1; i++)
        for (int j = 0; j < n - 1 - i; j++)
            if (a[j].dtb < a[j + 1].dtb) swap(a[j], a[j + 1]);
}
int main() {
    HS ds[4] = {{"An", 6.5}, {"Binh", 8}, {"Chi", 7}, {"Dung", 9}};
    sapXep(ds, 4);
    for (int i = 0; i < 4; i++) cout << ds[i].ten << " ";
}

